<template>
  <main class="reader-shell" :class="{ dark: resolvedTheme === 'dark' }">
    <header v-if="!focusMode" class="reader-toolbar">
      <AppLink :to="`/library/${route.params.slug}`" class="reader-back"><Icon name="ph:arrow-left-bold" /> 返回书影</AppLink>
      <div class="reader-title"><Icon name="ph:book-open-text-bold" /><span>{{ item?.title || '在线阅读' }}</span><b class="reader-progress">{{ progressPercent }}%</b><button v-if="savedCfi" type="button" class="progress-indicator" title="已保存阅读进度，点击继续阅读" @click="continueReading"><i /><span>继续阅读</span></button></div>
      <div class="reader-actions"><button type="button" title="切换主题" @click="toggleTheme"><Icon :name="resolvedTheme === 'dark' ? 'ph:sun-bold' : 'ph:moon-bold'" /></button><button type="button" title="沉浸式阅读" @click="focusMode = true"><Icon name="ph:corners-out-bold" /></button></div>
    </header>
    <section class="reader-stage" :class="{ focus: focusMode }" @wheel.prevent="handleWheel" @pointerdown="handlePointerDown" @pointerup="handlePointerUp"><div ref="bookEl" class="book-view" /><button v-if="focusMode" type="button" class="focus-exit" title="退出沉浸式阅读" @click="focusMode = false"><Icon name="ph:corners-in-bold" /></button><div v-if="loading" class="reader-loading"><Icon name="ph:circle-notch-bold" /><span>正在打开书页…</span></div><div v-if="!loading && !item?.epubMediaPath" class="reader-empty"><Icon name="ph:book-open-text-bold" /><h1>这本书还没有绑定 EPUB</h1><AppLink :to="`/library/${route.params.slug}`">返回详情</AppLink></div></section>
  </main>
</template>

<script setup lang="ts">
import type { LibraryItem } from '@/types/library'
const api = useApi(); const route = useRoute(); const { mediaUrl } = useMediaUrl(); const { visitorId, queueEvent } = useVisitor(); const { resolvedTheme, setTheme } = useTheme()
const bookEl = ref<HTMLElement | null>(null); const item = ref<LibraryItem | null>(null); const loading = ref(true); const focusMode = ref(false); const rendition = shallowRef<any>(null); const book = shallowRef<any>(null); const progressCfi = ref(''); const savedCfi = ref(''); const progressPercent = ref(0); const navigationBusy = ref(false); const pointerStart = ref<{ x: number; y: number } | null>(null); const contentCleanups: Array<() => void> = []; const attachedDocuments = new WeakSet<Document>()
const storageKey = computed(() => `corner:epub:${visitorId()}:${route.params.slug}`)
function applyReaderTheme() { const themes = rendition.value?.themes; if (!themes) return; themes.override('color', resolvedTheme.value === 'dark' ? '#e8e4d8' : '#34332f'); themes.override('background', resolvedTheme.value === 'dark' ? '#222521' : '#fbf7ee') }
function toggleTheme() { setTheme(resolvedTheme.value === 'dark' ? 'light' : 'dark'); nextTick(applyReaderTheme) }
async function turn(direction: 'next' | 'prev') { if (navigationBusy.value || !rendition.value) return; navigationBusy.value = true; try { await rendition.value[direction]() } finally { window.setTimeout(() => { navigationBusy.value = false }, 160) } }
function handleKey(event: KeyboardEvent) { if (['INPUT', 'TEXTAREA', 'SELECT'].includes((event.target as HTMLElement)?.tagName)) return; const key = event.key.toLowerCase(); if (['arrowdown', 'arrowright', 's', 'd'].includes(key)) { event.preventDefault(); void turn('next') } else if (['arrowup', 'arrowleft', 'w', 'a'].includes(key)) { event.preventDefault(); void turn('prev') } }
function handleWheel(event: WheelEvent) { if (Math.abs(event.deltaY) < 8 && Math.abs(event.deltaX) < 8) return; void turn(event.deltaY > 0 || event.deltaX > 0 ? 'next' : 'prev') }
function handlePointerDown(event: PointerEvent) { pointerStart.value = { x: event.clientX, y: event.clientY } }
function handlePointerUp(event: PointerEvent) { if (!pointerStart.value) return; const dx = event.clientX - pointerStart.value.x; const dy = event.clientY - pointerStart.value.y; pointerStart.value = null; if (Math.max(Math.abs(dx), Math.abs(dy)) < 34) return; void turn(Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? 'next' : 'prev') : (dy < 0 ? 'next' : 'prev')) }
async function continueReading() { if (savedCfi.value && rendition.value) { await rendition.value.display(savedCfi.value); progressCfi.value = savedCfi.value } }
function attachContentEvents() { const contents = rendition.value?.getContents?.() || []; for (const content of contents) { const doc = content.document as Document; if (attachedDocuments.has(doc)) continue; attachedDocuments.add(doc); const onWheel = (event: WheelEvent) => { event.preventDefault(); handleWheel(event) }; const onKey = (event: KeyboardEvent) => handleKey(event); let start: { x: number; y: number } | null = null; const onDown = (event: PointerEvent) => { start = { x: event.clientX, y: event.clientY } }; const onUp = (event: PointerEvent) => { if (!start) return; const dx = event.clientX - start.x; const dy = event.clientY - start.y; start = null; if (Math.max(Math.abs(dx), Math.abs(dy)) < 34) return; void turn(Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? 'next' : 'prev') : (dy < 0 ? 'next' : 'prev')) }; doc.addEventListener('wheel', onWheel, { passive: false }); doc.addEventListener('keydown', onKey); doc.addEventListener('pointerdown', onDown); doc.addEventListener('pointerup', onUp); contentCleanups.push(() => { doc.removeEventListener('wheel', onWheel); doc.removeEventListener('keydown', onKey); doc.removeEventListener('pointerdown', onDown); doc.removeEventListener('pointerup', onUp) }) } }
async function load() {
  try { item.value = await api.get<LibraryItem>(`/library/${route.params.slug}`); if (!item.value?.epubMediaPath || !bookEl.value) return
    // @ts-ignore epubjs 当前版本没有类型声明
    const ePub = (await import('epubjs')).default; book.value = ePub(mediaUrl(item.value.epubMediaPath)); rendition.value = book.value.renderTo(bookEl.value, { width: '100%', height: '100%', spread: 'none' });
    const saved = localStorage.getItem(storageKey.value) || ''; savedCfi.value = saved; await rendition.value.display(); applyReaderTheme(); attachContentEvents(); rendition.value.on('rendered', attachContentEvents)
    rendition.value.on('relocated', (location: any) => { const cfi = location?.start?.cfi || ''; if (!cfi) return; progressCfi.value = cfi; const percentage = Number(location?.start?.percentage ?? location?.end?.percentage ?? 0); progressPercent.value = Math.max(0, Math.min(100, Math.round(percentage * 100))); localStorage.setItem(storageKey.value, cfi); savedCfi.value = cfi; queueEvent({ action: 'content_read', path: cfi, contentType: 'library', contentId: item.value?.id, metadata: { slug: route.params.slug, progress: cfi, percentage: progressPercent.value } }) })
  } catch { item.value = null } finally { loading.value = false }
}
onMounted(() => { window.addEventListener('keydown', handleKey); void load() }); onBeforeUnmount(() => { window.removeEventListener('keydown', handleKey); contentCleanups.splice(0).forEach(cleanup => cleanup()); rendition.value?.destroy?.(); book.value?.destroy?.() }); useHead({ title: computed(() => `${item.value?.title || '在线阅读'} · 书影`) })
</script>

<style scoped>
.reader-shell{--reader-bg:#fbf7ee;--reader-ink:#34332f;display:flex;width:100%;height:100dvh;flex-direction:column;background:var(--reader-bg);color:var(--reader-ink);transition:background .45s ease,color .45s ease}.reader-shell.dark{--reader-bg:#222521;--reader-ink:#e8e4d8}.reader-toolbar{display:flex;height:58px;flex:0 0 58px;align-items:center;justify-content:space-between;gap:18px;padding:0 clamp(16px,4vw,54px);border-bottom:1px solid color-mix(in srgb,var(--reader-ink) 12%,transparent);background:color-mix(in srgb,var(--reader-bg) 88%,transparent);backdrop-filter:blur(18px)}.reader-back,.reader-title{display:inline-flex;align-items:center;gap:8px;color:inherit;font-size:.7rem;text-decoration:none}.reader-back{color:color-mix(in srgb,var(--reader-ink) 62%,transparent)}.reader-title{min-width:0;font-weight:700}.reader-title>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reader-progress{color:var(--c-primary);font-variant-numeric:tabular-nums}.progress-indicator{position:relative;display:inline-flex;align-items:center;gap:6px;padding:4px 7px;border:0;border-radius:999px;background:color-mix(in srgb,#43a977 10%,transparent);color:#43a977;cursor:pointer;font:inherit;font-size:.6rem}.progress-indicator i{width:7px;height:7px;border-radius:50%;background:#43a977;box-shadow:0 0 0 0 rgb(67 169 119 / 38%);animation:reader-breathe 1.8s ease-out infinite}.progress-indicator:hover::after{position:absolute;z-index:4;top:calc(100% + 8px);left:50%;padding:6px 9px;border-radius:7px;background:var(--reader-ink);color:var(--reader-bg);content:'已保存阅读进度 · 点击继续阅读';font-size:.56rem;white-space:nowrap;transform:translateX(-50%)}.reader-actions{display:flex;gap:6px}.reader-actions button,.focus-exit{display:grid;width:32px;height:32px;border:0;border-radius:9px;background:color-mix(in srgb,var(--reader-ink) 7%,transparent);color:inherit;cursor:pointer;place-items:center;transition:transform .25s ease,background .25s ease}.reader-actions button:hover,.focus-exit:hover{background:color-mix(in srgb,var(--reader-ink) 14%,transparent);transform:translateY(-1px)}.reader-stage{position:relative;display:flex;min-height:0;flex:1;justify-content:center;padding:clamp(18px,4vw,48px);cursor:grab;transition:padding .45s cubic-bezier(.16,1,.3,1)}.reader-stage:active{cursor:grabbing}.reader-stage.focus{padding:0}.book-view{width:min(880px,100%);height:100%;overflow:hidden;border-radius:18px;background:var(--reader-bg);box-shadow:0 12px 50px rgb(20 35 60 / 10%);transition:border-radius .45s ease,box-shadow .45s ease}.focus .book-view{width:100%;border-radius:0;box-shadow:none}.focus-exit{position:fixed;z-index:8;top:16px;right:16px;opacity:.36}.focus-exit:hover{opacity:1}.reader-loading,.reader-empty{position:absolute;inset:0;display:grid;align-content:center;justify-items:center;gap:10px;color:color-mix(in srgb,var(--reader-ink) 60%,transparent)}.reader-loading :deep(svg){animation:spin 1s linear infinite;font-size:1.5rem}.reader-empty :deep(svg){color:var(--c-primary);font-size:2.4rem}.reader-empty h1{margin:0;font-size:1.1rem}.reader-empty a{color:var(--c-primary);font-size:.72rem}@keyframes spin{to{transform:rotate(360deg)}}@keyframes reader-breathe{70%{box-shadow:0 0 0 7px rgb(67 169 119 / 0)}}
@media (max-width:640px){.reader-toolbar{gap:10px;padding:0 12px}.reader-back{font-size:0}.reader-back :deep(svg){font-size:1rem}.reader-title{flex:1;justify-content:center}.reader-title>span{max-width:32vw}.progress-indicator span{display:none}.reader-actions button{width:30px;height:30px}.reader-stage{padding:10px}.book-view{border-radius:12px}}
</style>
